def _prefixes(text):
    words = text.split()
    return [' '.join(words[:i]) for i in range(1, len(words) + 1)]


FORMS = {form.lower() for _, q, alt, *_ in BANK for form in [q] + alt}


def _row(kind, heard, label=None, forbid=None):
    """``label``: 'id' a hit must name (a miss is a lost hit), '?id' a hit may name (no hit is fine too), None: no hit is allowed."""
    want = label if label and not label.startswith('?') else None
    ok = {label.lstrip('?')} if label else set()
    return {'kind': kind, 'heard': heard.lower(), 'want': want, 'ok': ok, 'forbid': forbid, 'partials': _prefixes(heard.lower())}


SECOND_QUESTION = ('и чем отличается', 'и как считать')


def table(seed=5):
    """500 rows: {'kind', 'heard', 'partials', 'want', 'ok', 'forbid'}. A hit outside ``ok`` is a false accept; ``forbid``: the id the row was made against."""
    rnd = random.Random(seed)
    rows = [_row('plain', q, i) for i, q, alt, a, s in BANK]
    rows += [_row('paraphrase', text, label) for text, label in PARAPHRASE]
    rows += [_row('ear', text, label) for text, label in EAR]
    rows += [_row('foreign', text) for text in FOREIGN]
    rows += [_row('number', text, None if forbid and not forbid.startswith('?') else forbid, forbid if forbid and not forbid.startswith('?') else None) for text, forbid in NUMBERS]
    rows += [_row('not', text, None if forbid and not forbid.startswith('?') else forbid, forbid if forbid and not forbid.startswith('?') else None) for text, forbid in NOT]
    rows += [_row('two', text, label) for text, label in TWO]
    nouns = sorted({w for _, q, *_ in BANK for w in q.lower().split() if len(w) >= 6})
    for _ in range(40):                           # «не» put in after the first word of a bank question
        i, q, *_ = rnd.choice(BANK)
        words = q.split()
        text = ' '.join(words[:1] + ['не'] + words[1:])
        if text.lower() not in FORMS:                # «кто не может быть свидетелем» is a bank question of its own
            rows.append(_row('not', text, None, i))
    for _ in range(70):                           # one long word swapped for a word of another question: somebody else's question
        i, q, *_ = rnd.choice(BANK)
        words = q.split()
        spots = [k for k, w in enumerate(words) if len(w) >= 6]
        if not spots:
            continue
        k = rnd.choice(spots)
        lemmas = {a.atom for form in [q] + dict((b[0], b[2]) for b in BANK)[i] for a in _atoms(form)}
        other = rnd.choice([w for w in nouns if not {a.atom for a in _atoms(w)} & lemmas])
        rows.append(_row('foreign', ' '.join(words[:k] + [other] + words[k + 1:]), None, i))
    # unfinished: a whole bank question already heard, and the speech goes on with more significant words: the final is another question
    tails = ['и почему', 'для импорта', 'в две тысячи двадцатом году', 'для иностранцев', 'и чем отличается', 'в Казахстане', 'у собаки и кошки', 'и как считать', 'не в России']
    while len(rows) < 500:
        i, q, alt, a, s = rnd.choice(BANK)
        tail = rnd.choice(tails)
        # W11 (WAVE11 п.3): a second whole question joined by «и» is answered by its first part; a cut-off «и почему» or a qualifier still is not
        rows.append(_row('unfinished', q + ' ' + tail, '?' + i, None) if tail in SECOND_QUESTION else _row('unfinished', q + ' ' + tail, None, i))
    return rows[:500]
